CREATE TABLE destinations(id uuid PRIMARY KEY,owner_id uuid,provider varchar(64) NOT NULL,provider_reference varchar(256) NOT NULL,name varchar(200) NOT NULL,latitude numeric(10,7) NOT NULL,longitude numeric(10,7) NOT NULL,timezone varchar(64) NOT NULL,accessibility jsonb NOT NULL,source_version integer NOT NULL CHECK(source_version>0),created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),version integer NOT NULL CHECK(version>0),CHECK(latitude BETWEEN -90 AND 90),CHECK(longitude BETWEEN -180 AND 180));
CREATE UNIQUE INDEX destinations_provider_reference_active ON destinations(provider,provider_reference) WHERE deleted_at IS NULL;
CREATE TABLE routes(id uuid PRIMARY KEY,owner_id uuid,provider varchar(64) NOT NULL,provider_reference varchar(256) NOT NULL,origin_destination_id uuid NOT NULL REFERENCES destinations(id),destination_id uuid NOT NULL REFERENCES destinations(id),travel_mode varchar(16) NOT NULL CHECK(travel_mode IN('WALKING','CYCLING','DRIVING','TRANSIT','OTHER')),distance_meters integer NOT NULL CHECK(distance_meters BETWEEN 0 AND 100000000),duration_seconds integer NOT NULL CHECK(duration_seconds BETWEEN 0 AND 604800),polyline_ciphertext bytea NOT NULL,accessibility jsonb NOT NULL,valid_from timestamptz(3) NOT NULL,valid_until timestamptz(3),source_version integer NOT NULL CHECK(source_version>0),created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),version integer NOT NULL CHECK(version>0),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE UNIQUE INDEX routes_provider_reference_active ON routes(provider,provider_reference) WHERE deleted_at IS NULL; CREATE INDEX routes_destination_validity ON routes(destination_id,valid_until);
CREATE TABLE trips(id uuid PRIMARY KEY,owner_id uuid NOT NULL,state varchar(16) NOT NULL CHECK(state IN('ACTIVE','COMPLETED','CANCELLED')),destination_id uuid NOT NULL REFERENCES destinations(id),active_session_id uuid UNIQUE,started_at timestamptz(3) NOT NULL,completed_at timestamptz(3),cancelled_at timestamptz(3),outcome varchar(16) CHECK(outcome IN('COMPLETED','CANCELLED')),created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),purge_after timestamptz(3),version integer NOT NULL CHECK(version>0),CHECK((state='ACTIVE' AND completed_at IS NULL AND cancelled_at IS NULL AND outcome IS NULL) OR (state='COMPLETED' AND completed_at IS NOT NULL AND cancelled_at IS NULL AND outcome='COMPLETED') OR (state='CANCELLED' AND cancelled_at IS NOT NULL AND completed_at IS NULL AND outcome='CANCELLED')));
CREATE UNIQUE INDEX trips_one_active_owner ON trips(owner_id) WHERE state='ACTIVE' AND deleted_at IS NULL;
CREATE TABLE navigation_sessions(id uuid PRIMARY KEY,trip_id uuid NOT NULL REFERENCES trips(id),owner_id uuid NOT NULL,route_id uuid NOT NULL REFERENCES routes(id),destination_id uuid NOT NULL REFERENCES destinations(id),travel_mode varchar(16) NOT NULL CHECK(travel_mode IN('WALKING','CYCLING','DRIVING','TRANSIT','OTHER')),state varchar(16) NOT NULL CHECK(state IN('ACTIVE','COMPLETED','CANCELLED')),started_at timestamptz(3) NOT NULL,ended_at timestamptz(3),stop_reason varchar(16) CHECK(stop_reason IN('COMPLETED','CANCELLED')),created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),version integer NOT NULL CHECK(version>0),CHECK((state='ACTIVE' AND ended_at IS NULL AND stop_reason IS NULL) OR (state IN('COMPLETED','CANCELLED') AND ended_at IS NOT NULL AND stop_reason=state)));
ALTER TABLE trips ADD CONSTRAINT trips_active_session_fk FOREIGN KEY(active_session_id) REFERENCES navigation_sessions(id);
CREATE UNIQUE INDEX sessions_one_active_trip ON navigation_sessions(trip_id) WHERE state='ACTIVE' AND deleted_at IS NULL; CREATE UNIQUE INDEX sessions_one_active_owner ON navigation_sessions(owner_id) WHERE state='ACTIVE' AND deleted_at IS NULL;
CREATE TABLE visited_locations(id uuid PRIMARY KEY,trip_id uuid NOT NULL REFERENCES trips(id),owner_id uuid NOT NULL,destination_id uuid,coordinates_ciphertext bytea NOT NULL,visited_at timestamptz(3) NOT NULL,created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),version integer NOT NULL CHECK(version>0)); CREATE UNIQUE INDEX visited_location_order ON visited_locations(trip_id,visited_at,id);
CREATE TABLE landmarks(id uuid PRIMARY KEY,owner_id uuid,destination_id uuid,provider varchar(64) NOT NULL,provider_reference varchar(256) NOT NULL,name varchar(200) NOT NULL,coordinates_ciphertext bytea,accessibility jsonb NOT NULL,source_version integer NOT NULL CHECK(source_version>0),created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),version integer NOT NULL CHECK(version>0)); CREATE UNIQUE INDEX landmarks_provider_reference_active ON landmarks(provider,provider_reference) WHERE deleted_at IS NULL;
CREATE TABLE outbox_events(event_id uuid PRIMARY KEY,event_type varchar(128) NOT NULL,event_version integer NOT NULL,subject_type varchar(64) NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL,partition_key varchar(128) NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz(3) NOT NULL,available_at timestamptz(3) NOT NULL,published_at timestamptz(3),attempt_count integer NOT NULL DEFAULT 0,last_error_code varchar(64),created_at timestamptz(3) NOT NULL); CREATE INDEX outbox_available ON outbox_events(available_at,event_id);
CREATE TABLE inbox_events(consumer_name varchar(64) NOT NULL,event_id uuid NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL,received_at timestamptz(3) NOT NULL,processed_at timestamptz(3),result_code varchar(64) NOT NULL,PRIMARY KEY(consumer_name,event_id)); CREATE INDEX inbox_received ON inbox_events(received_at);
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY,original_event_id uuid NOT NULL,consumer_name varchar(64) NOT NULL,event_type varchar(128) NOT NULL,event_version integer NOT NULL,payload bytea NOT NULL,failure_code varchar(64) NOT NULL,attempt_count integer NOT NULL,first_failed_at timestamptz(3) NOT NULL,last_failed_at timestamptz(3) NOT NULL,resolved_at timestamptz(3),expires_at timestamptz(3) NOT NULL); CREATE INDEX dead_letter_expiry ON dead_letter_events(expires_at);
CREATE TABLE idempotency_records(id uuid PRIMARY KEY,environment varchar(32) NOT NULL,principal_id uuid NOT NULL,service varchar(64) NOT NULL,method varchar(16) NOT NULL,route_template varchar(256) NOT NULL,key_hash varchar(64) NOT NULL,request_hash varchar(64) NOT NULL,state varchar(16) NOT NULL CHECK(state IN('IN_PROGRESS','COMPLETED')),response_status integer,response_body bytea,response_headers jsonb,created_at timestamptz(3) NOT NULL,completed_at timestamptz(3),expires_at timestamptz(3) NOT NULL,UNIQUE(environment,principal_id,service,method,route_template,key_hash)); CREATE INDEX idempotency_expiry ON idempotency_records(expires_at);
